int rob(vector<int>& nums, int i, vector<int>& memo) {
    if (i >= (int)nums.size()) return 0;
    if (memo[i] != -1) return memo[i];
    int take = nums[i] + rob(nums, i + 2, memo);
    int skip = rob(nums, i + 1, memo);
    return memo[i] = max(take, skip);
}

int rob(vector<int>& nums) {
    int prev2 = 0, prev1 = 0;
    for (int x : nums) {
        int cur = max(prev1, prev2 + x);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

int lcs(string a, string b) {
    int n = a.size(), m = b.size();
    vector<vector<int>> dp(n+1, vector<int>(m+1, 0));
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            dp[i][j] = (a[i-1] == b[j-1])
                ? dp[i-1][j-1] + 1
                : max(dp[i-1][j], dp[i][j-1]);
    return dp[n][m];
}

// The progression to practise on every DP: recursion -> memo -> table -> O(1) space.

// 1. Top-down (memoised recursion).
static int robMemo(int[] a, int i, Integer[] memo) {
    if (i >= a.length) return 0;
    if (memo[i] != null) return memo[i];
    return memo[i] = Math.max(a[i] + robMemo(a, i + 2, memo), robMemo(a, i + 1, memo));
}

// 2. Bottom-up table.
static int robTab(int[] a) {
    int n = a.length;
    int[] dp = new int[n + 2];
    for (int i = n - 1; i >= 0; i--) dp[i] = Math.max(a[i] + dp[i + 2], dp[i + 1]);
    return dp[0];
}

// 3. Rolling — only the last two states are ever read.
static int rob(int[] a) {
    int take = 0, skip = 0;
    for (int i = a.length - 1; i >= 0; i--) {
        int cur = Math.max(a[i] + skip, take);
        skip = take; take = cur;
    }
    return take;
}

